addedCss:
/* Current Girl Talk cards, and the plain Jost Bold heading treatment Ali selected. */
.dyk-slim .dyk-media-cards{position:relative;background:var(--hp-coral)}
.dyk-slim .dyk-media-cards img{position:absolute;width:46%;height:auto;max-width:none;min-height:0;object-fit:contain;border-radius:3px;top:50%;transform:translateY(-50%)}
.dyk-slim .dyk-media-cards img:first-child{left:3%}
.dyk-slim .dyk-media-cards img:last-child{right:3%}
.intent>div:first-child>h2,.dyk-slim .dyk-copy{-webkit-text-stroke:0;text-shadow:none;font-family:Jost,sans-serif;font-weight:700}
.dyk-slim{background:linear-gradient(135deg,color-mix(in srgb,var(--hp-purple) 60%,var(--hp-ink)),color-mix(in srgb,var(--hp-cobalt) 50%,var(--hp-ink)))}
.intent>div:first-child>h2{color:#1b30bd}

.dyk-slim .dyk-media img[src$="fairy-writing-desk.png"]{object-position:left center}
